n("שנאל", "שנאל הוא כנראה כתיב עברי של שאנל, שם צרפתי שהיה במקור שם משפחה. השם מוכר בעולם בעיקר בזכות בית האופנה הצרפתי שנקרא כך. בעברית הכתיב בלי האות א נשמע מעט אחרת, וקרוב לשמות שמסתיימים באל.", ["שאנל"])
n("ימית", "ימית הוא שם עברי חדש שבא מהמילה ים, ופירושו של הים. ימית הייתה גם שמה של עיר בצפון סיני, שנבנתה בשנות השבעים ופונתה בשנות השמונים, אחרי הסכם השלום עם מצרים. השם מביא תמונה של חוף ושל מים פתוחים.", ["ים"])
n("גאלדא", "גאלדא הוא שם ביידיש, שבא מהמילה היידית גאלד, זהב. ביידיש מוכרות גם הצורות גולדה וגאלדע, ושמות של מתכות יקרות היו נפוצים כשמות של בנות. השם נשמר בקהילות חסידיות עד היום.", [])
n("מאטיל", "מאטיל הוא שם ביידיש, וכנראה הוא צורה של מטילדה, שם שבא מגרמנית עתיקה ופירושו חזקה בקרב. ביידיש מוכרות גם הצורות מאטל וטילא. השם היה נפוץ בקהילות של מזרח אירופה.", ["מאטל", "טילא"])
n("טמסגן", "טמסגן הוא שם באמהרית, שפת אתיופיה, ופירושו תודה או הודיה, מתוך הכרת טובה לאלוהים. שמות רבים באמהרית הם משפטים קצרים של תודה ושל ברכה. השם נפוץ בקרב יוצאי אתיופיה בארץ.", [])
n("ארינה", "ארינה הוא שם רוסי שבא מהשם היווני אירנה, שפירושו שלום. ברוסית ובשפות של מזרח אירופה השם נפוץ מאוד, ומוכרת גם הצורה אירינה. השם הגיע לארץ עם העלייה מברית המועצות.", ["אירנה"])
n("ניק", "ניק הוא קיצור של ניקולס, שם שבא מהיוונית ובנוי מהמילים ניצחון ועם. באנגלית ניק הוא גם שם בפני עצמו. השם קצר ופשוט, ונוח במשפחות שחיות בין שתי שפות.", ["ניקו", "ניקי"])
n("דוריאן", "דוריאן הוא שם שבא מהיוונית, ופירושו בן דוריס, שמו של אזור ביוון העתיקה ושל אחד השבטים היווניים. השם נעשה מוכר בזכות רומן ידוע מסוף המאה התשע עשרה. בעברית השם נשמע קרוב לדור ולדורון.", [])
n("סוניה", "סוניה היא צורת חיבה רוסית של סופיה, שם יווני שפירושו חוכמה. ברוסית השם נפוץ מאוד, והוא הגיע לשפות רבות. השם היה מוכר בארץ כבר בימי העלייה השנייה.", [])
n("קטרין", "קטרין הוא צורה של קתרין, שם שבא מהיוונית, ויש שקושרים אותו למילה קתרוס, טהור. השם נפוץ בשפות רבות של אירופה, ובצרפתית הוא נכתב כמעט כך. בעברית מוכרים גם הכתיבים קתרין וקטרינה.", [])
n("אלמז", "אלמז היא המילה באמהרית ליהלום, והיא קרובה למילה הערבית אלמאס. כשם, אלמז מביא את הרעיון של אבן יקרה, חזקה ונוצצת. השם נפוץ בקרב יוצאי אתיופיה בארץ, וניתן לבנות.", [])
n("תימור", "תימור הוא שם עברי שקשור לעץ התמר, ובעברית העתיקה תימורות הן עיטורים בדמות עצי תמר. התמר הוא אחד משבעת המינים, וגדל בארץ בעמקים החמים. בטורקית ובשפות של מרכז אסיה יש שם בצליל זהה, שפירושו ברזל.", ["תמר", "תומר"])
n("אנבל", "אנבל הוא שם בינלאומי, וכנראה הוא צירוף של השם אנה ושל המילה הצרפתית בל, יפה. השם נפוץ בצרפתית ובאנגלית. בסקוטלנד הוא מוכר כבר מימי הביניים, ושם יש לו גם הסבר אחר.", [])
n("ניראל", "ניראל הוא שם עברי חדש שבנוי מהמילים ניר ואל, ופירושו השדה של האל. המילה ניר מתארת שדה שנחרש לראשונה. השם נשמע גם כמו נר ואל, אור האל, ולכן יש לו שתי קריאות.", ["ניר"])
n("תמי", "תמי הוא צורת חיבה של תמר, שם של עץ התמר. באנגלית יש שם בצליל זהה, טמי, שהוא צורת חיבה של תמרה. השם היה נפוץ בארץ בשנות השישים והשבעים, ונשמע קליל ורך.", ["תמר"])
n("שובי", "שובי היא מילה עברית שפירושה חזרי, שובי אליי. בשיר השירים המילה חוזרת ארבע פעמים בקריאה אל השולמית. כשם, שובי מביא את הרעיון של חזרה הביתה ושל געגוע.", ["שובה"])
n("מירן", "מירן הוא שם עברי חדש, וכנראה הוא בנוי מהמילים מי ורן, ופירושו מי שר. המילה רן באה מהשורש ר־נ־ן, שירה ושמחה. השם נשמע קרוב גם למורן ולמירון, וניתן לבנים ולבנות.", [])
n("מידן", "מידן הוא שם עברי חדש, וכנראה הוא בנוי מהמילים מי ודן, ופירושו מי שופט. השם דן בא מהשורש ד־י־ן, שפוט ודין. השם נשמע גם כמו מידה ודין, ונבנה כנראה כשם חדש.", [])
n("כנה", "כנה היא מילה עתיקה לגפן צעירה שנשתלה זה עתה, והיא מופיעה בספר תהילים בתפילה לשמור עליה. בעברית של היום המילה מתארת גם בסיס, מקום שעליו מעמידים דבר. כשם, כנה מביא תמונה של צמח צעיר שגדל.", [])
n("אילנית", "אילנית הוא שם עברי חדש שבא מהמילה אילן, עץ. מאותה מילה באים גם השמות אילן ואילנה. השם היה נפוץ בארץ בשנות החמישים והשישים, והוא מוכר גם כשם במה של זמרת ישראלית ידועה.", ["אילנה"])
n("טמיר", "טמיר היא מילה עברית לנסתר ולחבוי, דבר שאינו גלוי לעין. מאותו שורש, ט־מ־ר, באות המילים טמון ומטמון. השם ניתן לבנים, ומוכרת גם צורת הנקבה טמירה.", ["טמירה"])
n("סמדר", "סמדר היא המילה העתיקה לפרח של הגפן ולענבים הקטנים שרק התחילו לגדול. בשיר השירים הגפנים סמדר נתנו ריח, כסימן לבוא האביב. השם היה נפוץ בארץ בשנות החמישים והשישים.", [])
n("קובי", "קובי הוא צורת חיבה של יעקב, שהייתה נפוצה מאוד בארץ. השם יעקב בא מהמילה עקב, ובמסורת הוא מוסבר בכך שיעקב נולד ואוחז בעקב של עשו. באנגלית מוכרת צורת חיבה דומה, ג׳ייק.", ["יעקב"])
n("נהרה", "נהרה היא מילה עתיקה לאור, והיא מופיעה בספר איוב. מאותו שורש באות המילים נהור, אור בארמית, ונהר, להאיר ולזרוח. כשם, נהרה מביא תמונה של אור שמופיע ומאיר.", ["נהורה"])
n("תובל", "תובל הוא שם מקראי, ובספר בראשית תובל קין מתואר כראשון לעובדי הנחושת והברזל. השם מופיע גם כשמו של עם רחוק ברשימות של התנ״ך. בעברית השם נשמע קרוב למילה תבל, העולם.", [])
n("קוראל", "קוראל הוא שם שבא מהמילה האנגלית לאלמוג, בעל החיים הימי שבונה שוניות צבעוניות. אלמוגים יש גם בים האדום, ליד אילת. בעברית השם נשמע גם כמו צירוף של קורא ואל.", [])
n("יה-לי", "יה־לי הוא שם עברי חדש שבנוי משתי מילים, יה ולי, ופירושו ה׳ שלי. המילה יה היא צורה קצרה של שם ה׳, והיא מופיעה בסוף שמות רבים. המקף מפריד בין שני חלקי השם.", [])
n("בוריס", "בוריס הוא שם סלאבי, וכנראה הוא בא מהמילה בורבה, מאבק, ופירושו לוחם. ברוסית ובבולגרית השם נפוץ מאוד. השם הגיע לארץ עם העלייה מברית המועצות, ונשמר במשפחות רבות.", [])
n("אוסנת", "אוסנת היא צורה של אסנת, אשתו של יוסף, בתו של כהן מצרי, ואמם של אפרים ומנשה. השם כנראה מצרי, ופירושו קשור לאלה מצרית. הכתיב עם האות ו מסמן את ההגייה, והוא נפוץ בעברית החדשה.", ["אסנת"])
n("אליחי", "אליחי הוא שם עברי חדש שבנוי משתי מילים, אלי וחי, ופירושו האל שלי חי. הצירוף הזה מזכיר את הקריאה חי ה׳, שמוכרת היטב בעברית הקדומה. מוכרת גם הצורה אלחי.", ["אלחי"])
n("לאיה", "לאיה הוא שם חדש, וכנראה הוא צורה של לאה, אחת מארבע האמהות. הכתיב עם האות י מסמן את ההגייה. בשפות של אירופה מוכרות צורות דומות, כמו ליאה ולאה.", ["לאה", "ליאה"])
n("איזבלה", "איזבלה היא צורה אירופית של השם העברי אלישבע, שהתפתחה בשפה הספרדית ובאיטלקית. השם נעשה מוכר בזכות מלכות בספרד, והוא נפוץ מאוד היום בשפות רבות. מוכרת גם הצורה הקצרה איזבל.", ["איזבל"])
n("פעסיל", "פעסיל הוא שם ביידיש, וכנראה הוא צורת חיבה של בתיה, עם הסיומת ל שמופיעה בצורות חיבה רבות ביידיש. ביידיש נכתבת התנועה באות ע. מוכרות גם הצורות פסיה ופעשא.", ["פסיה", "פעשא"])
n("נסלי", "נסלי הוא שם עברי חדש, וכנראה הוא בנוי מהמילים נס ולי, ופירושו נס בשבילי. המילה נס מתארת בעברית דבר מופלא, וגם דגל שמרימים גבוה. בטורקית יש שם בצליל דומה, נסלי, שמקורו אחר.", [])
n("אודאל", "אודאל הוא שם עברי חדש, וכנראה הוא בנוי מהמילים אודה ואל, ופירושו אודה לאלוהים. מאותו שורש באים גם השמות אודיה ויהודה. השם ניתן בעיקר לבנות, והוא מביע תודה.", ["אודיה"])
n("עתליה", "עתליה הוא שם מקראי, שמה של מלכה ששלטה ביהודה שש שנים, היחידה מבין מושלי יהודה שהייתה אישה. השם כנראה בנוי מהשורש ע־ת־ל ומהסיומת יה. בעברית החדשה השם נדיר, אבל מוכר.", [])
n("מריאל", "מריאל הוא שם חדש, וכנראה הוא צורה של מרים, עם הסיומת אל שמופיעה בשמות עבריים רבים. בשפה הספרדית ובצרפתית יש שם בצליל דומה, מריאל. השם ניתן בעיקר לבנות.", ["מרים"])
n("גדי", "גדי הוא שמו של בן העז, הצעיר, שקופץ בין הסלעים, ומשם בא השם של עין גדי. גדי הוא גם צורת חיבה של גדעון ושל גד. השם היה נפוץ בארץ בשנות החמישים והשישים.", ["גד"])
n("לימאי", "לימאי הוא שם עברי חדש, וכנראה הוא בנוי מהמילה לי ומשם החודש מאי. יש גם הסבר לפיו השם בא מהמילה ים, כמו ימאי, איש ים. השם נדיר וחדש, והוא ניתן בעיקר לבנות.", [])
n("לי-שי", "לי־שי הוא שם עברי חדש שבנוי משתי מילים, לי ושי, ופירושו יש לי מתנה. המילה שי היא מילה עתיקה למתנה. המקף מפריד בין שני חלקי השם, ומוכרת גם הצורה לישי.", ["לישי"])
n("אופאל", "אופאל הוא כתיב של אופל, אבן חן ססגונית שמחזירה את האור בצבעים רבים. הכתיב עם האות א מסמן את ההגייה של התנועה השנייה. המילה באה מהלטינית, ובמקור כנראה משפה של הודו.", ["אופל"])
n("ילין", "ילין הוא שם עברי חדש, וגם שם משפחה ירושלמי ותיק, של משפחה שחיה בעיר כבר לפני יותר ממאה וחמישים שנה. מקור השם לא ברור, וכנראה הוא נבנה מצליל שנשמע טוב. השם ניתן בעיקר לבנות.", [])
n("רמי", "רמי הוא שם עברי שבא מהמילה רם, נעלה וגבוה, ופירושו הרם שלי. הוא גם צורת חיבה של שמות כמו אברהם ורמיה. השם היה נפוץ בארץ בשנות החמישים והשישים.", ["רם"])
n("סנדרה", "סנדרה היא קיצור של אלכסנדרה, צורת הנקבה של אלכסנדר, שם יווני שפירושו מגן על האנשים. באיטלקית ובאנגלית סנדרה נעשה שם בפני עצמו. השם היה נפוץ בשנות השבעים.", [])
n("לינה", "לינה הוא שם שנפוץ בשפות רבות, וכנראה הוא קיצור של שמות כמו קרולינה, אדלינה ופאולינה. בערבית יש שם בצליל זהה, שפירושו עץ תמר רך. בעברית המילה לינה מתארת גם שינה בלילה.", ["לין", "לנה"])
n("איידן", "איידן הוא שם אירי, שבא מהמילה האירית לאש, ופירושו אש קטנה. השם נפוץ מאוד באנגלית בשנים האחרונות. בעברית הוא נשמע קרוב לעדן, ולכן הוא נוח גם במשפחות שחיות בין עברית לאנגלית.", [])
n("מורין", "מורין הוא שם אירי, צורה של מרים, שהתפתחה באירית כצורת חיבה. באנגלית השם היה נפוץ באמצע המאה העשרים. בעברית הוא נשמע קרוב למורן, שיח ירוק־עד.", ["מורן"])
n("רעכיל", "רעכיל הוא הצורה היידית של רחל, אחת מארבע האמהות. ביידיש נכתבת התנועה באות ע, והאות כ מחליפה את ח. השם היה נפוץ בקהילות של מזרח אירופה, ונשמר בקהילות חסידיות.", ["רחל"])
n("שובה", "שובה היא מילה עברית שפירושה חזרה, והיא קשורה גם למילה תשובה. כשם, שובה מביא את הרעיון של חזרה הביתה ושל שלווה. השם נשמע קרוב לשובי, שבנוי מאותה מילה.", ["שובי"])
n("קרולינה", "קרולינה היא צורת הנקבה של קרל, שם שבא מגרמנית עתיקה ופירושו אדם חופשי. השם נפוץ בשפות רבות של אירופה, ובאנגלית מוכרת הצורה קרוליין. בארצות הברית שתי מדינות נקראות על שם זה.", [])
n("פרלה", "פרלה היא המילה לפנינה בכמה שפות, כמו בשפה הספרדית ובאיטלקית. בלדינו פרלה היה שם נפוץ בקהילות של יהודי ספרד. ביידיש מוכר שם דומה, פערל, ובעברית פנינה.", ["פרל"])
n("קסניה", "קסניה הוא שם רוסי שבא מהמילה היוונית קסניה, הכנסת אורחים. ברוסית ובאוקראינית השם נפוץ, ומוכרות גם הצורות אוקסנה וכסניה. השם הגיע לארץ עם העלייה מברית המועצות.", [])
n("אנטוני", "אנטוני הוא שם בינלאומי שבא מהשם הלטיני אנטוניוס, שמה של משפחה רומית ידועה. השם נפוץ באנגלית, ובשפות אחרות מוכרות הצורות אנטוניו ואנטואן. מוכרת גם צורת הנקבה אנטוניה.", ["אנטוניה"])
n("רביב", "רביב היא מילה עתיקה לטיפות גשם קלות, שיורדות על האדמה ומרוות אותה. בשירה העברית הקדומה רביבים הם גם תמונה של מילים טובות שיורדות כמו גשם. השם ניתן בעיקר לבנים, ומוכרת גם צורת הנקבה רביבה.", ["רביבה"])
n("בלן", "בלן הוא שם קצר וחדש, וכנראה הוא קשור למילה הצרפתית בל, יפה. בשפות אחרות יש לשם צליל דומה עם מקורות שונים. השם נדיר, וניתן בעיקר לבנות, והוא קצר וקליל.", [])
n("פיטר", "פיטר הוא הצורה האנגלית של השם היווני פטרוס, שפירושו סלע. השם נפוץ מאוד בשפות רבות, ובשפות אחרות מוכרות הצורות פייר ופטר. בעברית מוכר גם הכתיב פטר.", ["פטר"])
n("אבידן", "אבידן הוא שם מקראי שבנוי מהמילים אבי ודן, ופירושו אבי הוא השופט. בספר במדבר אבידן בן גדעוני הוא נשיא שבט בנימין במדבר. בעברית החדשה השם נדיר, ונשמע קרוב לאביב ולעידן.", [])
n("לינס", "לינס הוא שם חדש, וכנראה הוא צורה של לין או של לינה, עם סיומת שמזכירה את האנגלית. המקור לא ברור, והשם נבנה כנראה בעיקר מצליל שנשמע טוב. השם ניתן בעיקר לבנות.", [])
n("שחק", "שחק היא מילה עתיקה לשמיים, וגם לענן דק, והיא מוכרת מהשירה העברית הקדומה. מאותה מילה באה המילה גורד שחקים, בניין גבוה מאוד. כשם, שחק מביא תמונה של גובה ושל מרחב.", [])
n("בן-ציון", "בן־ציון הוא שם עברי שבנוי משתי מילים, בן וציון, ופירושו בן של ציון, של ירושלים. השם היה נפוץ בקהילות יהודיות רבות, והוא ביטוי של אהבה לארץ ישראל. המקף מפריד בין שני חלקי השם.", [])
